  "users": [
    { "id": "U01", "name": "Leela",    "email": "leela@gmail.com",    "password": "Leela@123" },
    { "id": "U02", "name": "Katy",     "email": "katy@gmail.com",     "password": "Katy@12354" },
    { "id": "U03", "name": "Jyosthna", "email": "jyosthna@gmail.com", "password": "Jyos@123" }
  ]
