await writeProjectFile("week4/generated/day4-data-driven.spec.ts", `// Week 4, Day 4 — one test body, many sets of data.
//
// Three credentials, one test. Adding a fourth user means editing
// day4-users.json and nothing else.
//
// Written by a cell in week4/day4_2.ipynb. Run it yourself:
//   npx playwright test week4/generated/day5-data-driven.spec.ts
import { test, expect } from "@playwright/test";
import testData from "./day4-users.json";

test.describe("Every demo account can sign in", () => {
  // The loop runs while Playwright COLLECTS tests, so each record becomes its own
  // named test with its own pass/fail. One record failing hides nothing.
  for (const user of testData.users) {
    test(\`\${user.id} — \${user.name} signs in\`, async ({ page }) => {
      await page.goto("/");
      await page.getByPlaceholder("Enter Email").fill(user.email);
      await page.getByPlaceholder("Enter Password").fill(user.password);
      await page.getByRole("button", { name: "Login" }).click();

      await expect(page).toHaveURL(/dashboard/);
      // Assert against the data, never against a value typed a second time.
      await expect(page.getByText(user.name)).toBeVisible();

      await page.getByRole("button", { name: "LogOut" }).click();
      await expect(page.getByPlaceholder("Enter Email")).toBeVisible();
    });
  }
});
`);

await runSpec("week4/generated/day4-data-driven.spec.ts");

type Case = { id: string; expected: string };

function planFor(c: Case): string {
  if (c.expected === "dashboard") {
    return "assert URL is /dashboard AND the name is visible";
  } else if (c.expected === "blocked") {
    return "assert URL is NOT /dashboard AND no name anywhere";
  } else if (c.expected === "disabled") {
    return "assert the Login button is disabled; never click it";
  } else {
    throw new Error(`Unknown expected value: ${c.expected}`);
  }
}

for (const c of [{ id: "TC01", expected: "dashboard" }, { id: "TC02", expected: "blocked" }, { id: "TC04", expected: "disabled" }]) {
  console.log(`${c.id} -> ${planFor(c)}`);
}
try {
