import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 4 Day 1.1, concept 2.

await writeProjectFile("week4/generated/day4-login-cases.json", `{
  "cases": [
    {
      "id": "TC01", "description": "valid credentials reach the dashboard",
      "email": "leela@gmail.com", "password": "Leela@123",
      "expected": "dashboard"
    },
    {
      "id": "TC02", "description": "correct email, wrong password is refused",
      "email": "leela@gmail.com", "password": "WrongPass1",
      "expected": "blocked"
    },
    {
      "id": "TC03", "description": "unknown email is refused",
      "email": "nobody@gmail.com", "password": "Leela@123",
      "expected": "blocked"
    },
    {
      "id": "TC04", "description": "blank email disables the button",
      "email": "", "password": "Leela@123",
      "expected": "disabled"
    },
    {
      "id": "TC05", "description": "blank password disables the button",
      "email": "leela@gmail.com", "password": "",
      "expected": "disabled"
    },
    {
      "id": "TC06", "description": "both blank disables the button",
      "email": "", "password": "",
      "expected": "disabled"
    }
  ]
}
`);

await writeProjectFile("week4/generated/day4-login-cases.spec.ts", `// Week 4, Day 4 — data-driven where the EXPECTED RESULT also comes from the file.
//
// The previous spec assumed every record succeeds. Here each record carries what
// should happen, and the test branches on it. That branch is the whole lesson:
// the data decides which assertion runs.
//
// Three outcomes, all verified against the live app:
//   dashboard - signed in, name visible
//   blocked   - button clickable, login refused, still on the login page
//   disabled  - a blank field leaves the button disabled; it cannot be clicked
//
// Written by a cell in week4/day4_3.ipynb. Run it yourself:
//   npx playwright test week4/generated/day4-login-cases.spec.ts
import { test, expect } from "@playwright/test";
import testData from "./day4-login-cases.json";

test.describe("Login — all six scenarios from one file", () => {
  for (const testCase of testData.cases) {
    test(\`\${testCase.id} — \${testCase.description}\`, async ({ page }) => {
      await page.goto("/");

      // fill() rejects an empty string on some inputs, and a blank field is the
      // point of TC04-TC06, so only type when there is something to type.
      if (testCase.email) {
        await page.getByPlaceholder("Enter Email").fill(testCase.email);
      }
      if (testCase.password) {
        await page.getByPlaceholder("Enter Password").fill(testCase.password);
      }

      const loginButton = page.getByRole("button", { name: "Login" });

      if (testCase.expected === "disabled") {
        // Client-side validation: nothing to submit, so nothing to assert about
        // a response. The button itself is the expected result.
        await expect(loginButton).toBeDisabled();
        return;
      }

      await expect(loginButton).toBeEnabled();
      await loginButton.click();

      if (testCase.expected === "dashboard") {
        await expect(page).toHaveURL(/dashboard/);
        await expect(page.getByText("Leela")).toBeVisible();
      } else if (testCase.expected === "blocked") {
        // No error text is shown at all, so the assertion is that we did NOT get
        // in: still on the login form, and no signed-in name anywhere.
        await expect(page).not.toHaveURL(/dashboard/);
        await expect(page.getByPlaceholder("Enter Email")).toBeVisible();
        await expect(page.getByText("Leela")).toHaveCount(0);
      } else {
        throw new Error(\`Unknown expected value: \${testCase.expected}\`);
      }
    });
  }
});
`);

await runSpec("week4/generated/day4-login-cases.spec.ts");

