import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 4 Day 1.1, concept 2.

await writeProjectFile("week4/generated/day4-excel-csv.csv", `id,description,email,password,expected
TC01,valid credentials,leela@gmail.com,Leela@123,dashboard
TC02,wrong password,leela@gmail.com,WrongPass1,blocked
TC03,unknown email,nobody@gmail.com,Leela@123,blocked
TC04,blank email, ,Leela@123,disabled
TC05,blank password,leela@gmail.com, ,disabled
TC06,both blank, , ,disabled
`);

await writeProjectFile("week4/generated/day4-excel-csv.spec.ts", `// Week 4, Day 4 — the same test data, from Excel and from CSV.
//
// Nothing about the test changes. Only where the rows come from. That is the
// whole point: Playwright reads JSON natively, and every other format becomes
// JSON-shaped objects before your test ever sees it.
//
// Written by a cell in week4/day4_2.ipynb. Run it yourself:
//   npx playwright test week4/generated/day4-excel-csv.spec.ts
import { test, expect } from "@playwright/test";
import { readFileSync } from "node:fs";
import * as path from "node:path";
import * as XLSX from "xlsx";
import { parse } from "csv-parse/sync";

type LoginCase = {
  id: string;
  description: string;
  email: string;
  password: string;
  expected: string;
};

const dataDir = __dirname;

/**
 * Excel: read the bytes, then hand them to XLSX.read().
 *
 * Note we do NOT use XLSX.readFile(). It needs SheetJS's fs wiring, which is not
 * available in every module system — reading the buffer ourselves works everywhere
 * and mirrors the CSV path below.
 */
function fromExcel(file: string): LoginCase[] {
  const workbook = XLSX.read(readFileSync(path.join(dataDir, file)));
  // A workbook holds sheets; a sheet holds cells. Take the first sheet.
  const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
  return XLSX.utils.sheet_to_json<LoginCase>(firstSheet);
}

/** CSV: read the text, then parse it. \`columns: true\` uses row 1 as field names. */
function fromCsv(file: string): LoginCase[] {
  return parse(readFileSync(path.join(dataDir, file), "utf-8"), {
    columns: true,
    skip_empty_lines: true,
  }) as LoginCase[];
}

const excelCases = fromExcel("day4-excel-csv.xlsx");
const csvCases = fromCsv("day4-excel-csv.csv");

test.describe("Both formats yield the same rows", () => {
  test("Excel and CSV parse to identical data", () => {
    expect(excelCases).toHaveLength(6);
    expect(csvCases).toHaveLength(6);
    expect(csvCases).toEqual(excelCases);
  });

  test("the sheet name is readable, not guessed", () => {
    const workbook = XLSX.read(readFileSync(path.join(dataDir, "day4-excel-csv.xlsx")));
    expect(workbook.SheetNames).toEqual(["LoginCases"]);
  });
});

// One loop, run twice — once per source. The test body is identical.
for (const [source, cases] of [["excel", excelCases], ["csv", csvCases]] as const) {
  test.describe(\`Login cases from \${source}\`, () => {
    for (const testCase of cases) {
      test(\`\${source} \${testCase.id} — \${testCase.description}\`, async ({ page }) => {
        await page.goto("/");

        // Blank cells cannot be stored as truly empty in a spreadsheet without
        // vanishing from sheet_to_json, so the data files use a single space.
        // Treat whitespace-only as blank rather than typing it.
        const email = testCase.email.trim();
        const password = testCase.password.trim();

        if (email) await page.getByPlaceholder("Enter Email").fill(email);
        if (password) await page.getByPlaceholder("Enter Password").fill(password);

        const loginButton = page.getByRole("button", { name: "Login" });

        if (testCase.expected === "disabled") {
          await expect(loginButton).toBeDisabled();
          return;
        }

        await expect(loginButton).toBeEnabled();
        await loginButton.click();

        if (testCase.expected === "dashboard") {
          await expect(page).toHaveURL(/dashboard/);
          await expect(page.getByText("Leela")).toBeVisible();
        } else if (testCase.expected === "blocked") {
          await expect(page).not.toHaveURL(/dashboard/);
          await expect(page.getByText("Leela")).toHaveCount(0);
        } else {
          throw new Error(\`Unknown expected value: \${testCase.expected}\`);
        }
      });
    }
  });
}
`);

await runSpec("week4/generated/day4-excel-csv.spec.ts");

